namespace ZARI.Domain.Entities;

using ZARI.Domain.Common;

/// <summary>
/// One row per employee per 13th-month run — entirely regenerated by ComputeThirteenthMonthPayRunCommand
/// while the run is DRAFT, never edited directly, and never recalculated once POSTED (same "the
/// table IS the report" idiom as PayrollLine).
/// </summary>
public sealed class ThirteenthMonthPayLine : AuditableEntity
{
    public Guid ThirteenthMonthPayRunId { get; set; }
    public ThirteenthMonthPayRun ThirteenthMonthPayRun { get; set; } = default!;
    public Guid EmployeeId { get; set; }
    public Employee Employee { get; set; } = default!;

    public decimal TotalBasicPay { get; set; }
    public decimal ThirteenthMonthPay { get; set; }
}
